<?php require_once __DIR__.'/bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='save_product'){$id=(int)($_POST['id']??0);$title=trim((string)($_POST['title']??''));$vid=trim((string)($_POST['cj_vid']??''));$sku=trim((string)($_POST['sku']??''));$pid=trim((string)($_POST['cj_pid']??''));$desc=trim((string)($_POST['description']??''));$img=trim((string)($_POST['image_url']??''));$cost=filter_var($_POST['supplier_cost']??null,FILTER_VALIDATE_FLOAT);$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);if($title===''||$vid===''||$cost===false||$cost<0||$price===false||$price<0||($img!==''&&!filter_var($img,FILTER_VALIDATE_URL))){flash('Check title, CJ variant ID, prices and image URL.');header('Location: admin.php');exit;}try{if($id){$s=$pdo->prepare('UPDATE products SET cj_pid=?,cj_vid=?,sku=?,title=?,description=?,image_url=?,supplier_cost=?,price=?,active=? WHERE id=?');$s->execute([$pid?:null,$vid,$sku?:null,$title,$desc,$img?:null,$cost,$price,isset($_POST['active'])?1:0,$id]);}else{$s=$pdo->prepare('INSERT INTO products(cj_pid,cj_vid,sku,title,description,image_url,supplier_cost,price,active) VALUES(?,?,?,?,?,?,?,?,1)');$s->execute([$pid?:null,$vid,$sku?:null,$title,$desc,$img?:null,$cost,$price]);}flash('Product saved.');}catch(PDOException $e){error_log('Product save: '.$e->getMessage());flash('Could not save. CJ variant ID must be unique.');}header('Location: admin.php');exit;}if($action==='toggle'){$s=$pdo->prepare('UPDATE products SET active=1-active WHERE id=?');$s->execute([(int)($_POST['id']??0)]);header('Location: admin.php');exit;}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:null;}$products=$pdo->query('SELECT * FROM products ORDER BY id DESC')->fetchAll();$orders=$pdo->query('SELECT id,order_number,customer_name,subtotal,payment_status,fulfilment_status,created_at FROM orders ORDER BY id DESC LIMIT 30')->fetchAll();page_start('Admin dashboard');?><h1>Store administration</h1><p class="muted">Manage catalogue and review recent orders. CJ product API search/import can be added after confirming the product query response shape for your CJ account.</p><div class="panel"><h2><?= $edit?'Edit product':'Add a CJ product'?></h2><p class="muted small">Enter the exact CJ variant ID (vid) and SKU from CJ. Use the current supplier cost and set your own retail price.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_product"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="row"><div><label>Product title *</label><input name="title" required value="<?=e($edit['title']??'')?>"></div><div><label>CJ variant ID (vid) *</label><input name="cj_vid" required value="<?=e($edit['cj_vid']??'')?>"></div></div><div class="row"><div><label>CJ product ID</label><input name="cj_pid" value="<?=e($edit['cj_pid']??'')?>"></div><div><label>CJ SKU</label><input name="sku" value="<?=e($edit['sku']??'')?>"></div></div><label>Description</label><textarea name="description" rows="3"><?=e($edit['description']??'')?></textarea><label>Image URL (HTTPS)</label><input name="image_url" type="url" value="<?=e($edit['image_url']??'')?>"><div class="row"><div><label>Supplier cost (<?=e(getenv('STORE_CURRENCY')?:'USD')?>)</label><input name="supplier_cost" type="number" min="0" step="0.01" required value="<?=e((string)($edit['supplier_cost']??'0.00'))?>"></div><div><label>Retail price (<?=e(getenv('STORE_CURRENCY')?:'USD')?>)</label><input name="price" type="number" min="0" step="0.01" required value="<?=e((string)($edit['price']??''))?>"></div></div><?php if($edit):?><label><input type="checkbox" name="active" value="1" style="width:auto" <?=!empty($edit['active'])?'checked':''?>> Visible in store</label><?php endif ?><button>Save product</button> <?php if($edit):?><a class="btn secondary" href="admin.php">Cancel</a><?php endif ?></form></div><h2>Catalogue</h2><div class="panel"><table><thead><tr><th>Product</th><th>CJ vid</th><th>Cost / Retail</th><th>State</th><th></th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><?=e($p['title'])?></td><td><?=e($p['cj_vid'])?></td><td><?=money($p['supplier_cost'])?> / <?=money($p['price'])?></td><td><?=$p['active']?'Visible':'Hidden'?></td><td><a href="?edit=<?=(int)$p['id']?>">Edit</a> <form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="secondary">Toggle</button></form></td></tr><?php endforeach ?></tbody></table></div><h2>Recent orders</h2><div class="panel"><table><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Payment</th><th>Fulfilment</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=e($o['order_number'])?></td><td><?=e($o['customer_name'])?></td><td><?=money($o['subtotal'])?></td><td><?=e($o['payment_status'])?></td><td><?=e($o['fulfilment_status'])?></td></tr><?php endforeach ?></tbody></table></div><?php page_end();?>
